import { LitElement, css, html } from 'lit';
import { customElement, state } from 'lit/decorators.js';

@customElement('vrutti-app')
export class VruttiApp extends LitElement {
  @state()
  private isLoading = true;

  @state()
  private greeting = '';

  connectedCallback() {
    super.connectedCallback();
    const hour = new Date().getHours();
    if (hour >= 5 && hour < 12) this.greeting = 'Good Morning';
    else if (hour >= 12 && hour < 17) this.greeting = 'Good Afternoon';
    else if (hour >= 17 && hour < 22) this.greeting = 'Good Evening';
    else this.greeting = 'Good Night';

    setTimeout(() => {
      this.isLoading = false;
    }, 2500);
  }

  static styles = css`
    :host {
      display: flex;
      flex-direction: column;
      height: 100vh;
      --vrutti-bg: hsl(230, 25%, 8%);
      --vrutti-surface: hsla(230, 25%, 15%, 0.6);
      --vrutti-surface-border: hsla(230, 25%, 25%, 0.4);
      --vrutti-accent: hsl(210, 100%, 75%);
      --vrutti-text: hsl(220, 25%, 75%);
      --vrutti-text-bright: hsl(220, 25%, 95%);
      background-color: var(--vrutti-bg);
      color: var(--vrutti-text);
      font-family: 'Inter', -apple-system, sans-serif;
    }
    
    header {
      height: 35px;
      background: var(--vrutti-surface);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      display: flex;
      align-items: center;
      justify-content: space-between;
      border-bottom: 1px solid var(--vrutti-surface-border);
      -webkit-app-region: drag;
      user-select: none;
    }
    
    .header-left {
      display: flex;
      align-items: center;
      padding-left: 10px;
    }
    .logo-img {
      width: 16px;
      height: 16px;
      margin-right: 12px;
    }
    .menu-item {
      padding: 4px 8px;
      font-size: 13px;
      color: #a6accd;
      -webkit-app-region: no-drag;
      cursor: default;
      border-radius: 4px;
    }
    .menu-item:hover {
      background: var(--vrutti-surface-border);
      color: var(--vrutti-text-bright);
    }
    .header-right {
      display: flex;
      height: 100%;
    }
    .actions button {
      background: none;
      border: none;
      color: var(--vrutti-text);
      width: 46px;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      -webkit-app-region: no-drag;
      cursor: default;
      padding: 0;
      transition: background 0.2s ease, color 0.2s ease;
    }
    .actions button:hover {
      background: var(--vrutti-surface-border);
      color: var(--vrutti-text-bright);
    }
    .actions button.close-btn:hover {
      background-color: #e81123;
      color: white;
    }
    
    .logo {
      font-weight: 600;
      color: #82aaff;
    }

    .main {
      display: flex;
      flex: 1;
      overflow: hidden;
    }
    
    vrutti-sidebar {
      width: 250px;
      background: var(--vrutti-surface);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-right: 1px solid var(--vrutti-surface-border);
      transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    }
    
    vrutti-editor {
      flex: 1;
      background-color: transparent;
    }
    
    .splash-screen {
      position: absolute;
      top: 35px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--vrutti-bg);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      z-index: 1000;
      transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .splash-screen.hidden {
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
    }
    .greeting {
      font-size: 2rem;
      font-weight: 300;
      color: #a6accd;
      margin-bottom: 8px;
    }
    .sub-greeting {
      font-size: 1.1rem;
      color: #717cb4;
      font-style: italic;
    }
    .splash-logo {
      width: 48px;
      height: 48px;
      margin-bottom: 24px;
      animation: pulse 2s infinite ease-in-out;
      object-fit: contain;
    }
    @keyframes pulse {
      0% { transform: scale(0.95); opacity: 0.7; }
      50% { transform: scale(1.05); opacity: 1; }
      100% { transform: scale(0.95); opacity: 0.7; }
    }
  `;

  render() {
    return html`
      <header @mousedown="${(e: MouseEvent) => {
        const target = e.target as HTMLElement;
        if (target.tagName !== 'BUTTON' && !target.closest('button') && !target.classList.contains('menu-item')) {
          if ((window as any).startWindowDrag) {
            (window as any).startWindowDrag();
          }
        }
      }}">
        <div class="header-left">
          <img class="logo-img" src="data:image/png;base64," style="display: block; width: 16px; height: 16px; object-fit: contain;" />
          <div class="menu-item">File</div>
          <div class="menu-item">Edit</div>
          <div class="menu-item">Selection</div>
          <div class="menu-item">View</div>
        </div>
        
        <div class="header-right actions">
          <button @click=${() => (window as any).minimizeWindow()}>
            <svg viewBox="0 0 10 1" width="10" height="1"><rect width="10" height="1" fill="currentColor"/></svg>
          </button>
          <button @click=${() => (window as any).maximizeWindow()}>
            <svg viewBox="0 0 10 10" width="10" height="10" fill="none" stroke="currentColor"><rect x="0.5" y="0.5" width="9" height="9"/></svg>
          </button>
          <button class="close-btn" @click=${() => (window as any).closeWindow()}>
            <svg viewBox="0 0 10 10" width="10" height="10" stroke="currentColor"><path d="M0,0 L10,10 M10,0 L0,10" stroke-width="1.5"/></svg>
          </button>
        </div>
      </header>
      
      <div class="splash-screen ${this.isLoading ? '' : 'hidden'}">
        <img class="splash-logo" src="data:image/png;base64," />
        <div class="greeting">${this.greeting}, User</div>
        <div class="sub-greeting">prepping your beast...</div>
      </div>
      
      <div class="main">
        <vrutti-sidebar></vrutti-sidebar>
        <div style="flex: 1; display: flex; align-items: center; justify-content: center; opacity: 0.1; pointer-events: none;">
        <img src="data:image/png;base64," style="max-width: 512px; max-height: 512px; width: 40vw; height: 40vw; object-fit: contain;" />
      </div>
      </div>
    `;
  }
}



